window.products.push({"id":1187693,"name":"Garmin 010-12676-00 Portable Ice Fishing Kit (with GT10HN-IF Transducer)","category":"electronics","retail price":314.45,"sale price":null,"image":"https://m.media-amazon.com/images/I/81rg3CXSJrL._AC_SL1500_.jpg","description":"Take your compatible ECHOMAP CHIRP anywhere on the ice with this rugged, portable fishing kit. The GT10HN-IF ice fishing transducer features Garmin CHIRP traditional sonar with narrow, 8-16 degree beam angle for crisp, clear images and excellent target separation. The included carrying bag protects and carries your device and accessories while the built-in cable management and storage means you can easily take it anywhere on the ice.","images":["https://m.media-amazon.com/images/I/81rg3CXSJrL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"GARMIN ELEC.","source_asin":"B077N2PGKD","category_path":"Electronics"},"sku":"BM-1187693","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B077N2PGKD","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B077N2PGKD","price_pending":true,"merchant_ready":false});
