window.products.push({"id":1187754,"name":"ChromaCast MINI HDMI to Standard HDMI Cable (20 feet)","category":"electronics","retail price":6.98,"sale price":null,"image":"https://m.media-amazon.com/images/I/61zBWHQ6-RL._AC_SL1200_.jpg","description":"Mini HDMI enables delivery of both high-definition video and multichannel, digital audio from your portable digital devices to your home theater. It offers an ideal way to connect digital camcorders and digital cameras with mini HDMI (HDMI C) ports to HDTVs or AV receivers with full-size HDMI (HDMI A) ports.","images":["https://m.media-amazon.com/images/I/61zBWHQ6-RL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"ChromaCast","source_asin":"B00J819CMY","category_path":"Electronics"},"sku":"BM-1187754","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00J819CMY","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B00J819CMY","price_pending":true,"merchant_ready":false});
